function windowAverages(arr, k) {
  const result = [];
  let windowSum = 0;

  for (let right = 0; right < arr.length; right++) {
    windowSum += arr[right];

    if (right >= k - 1) {
      result.push(windowSum / k);
      windowSum -= arr[right - k + 1];
    }
  }
  return result;
}
